def transform(grid):
    g = np.array(grid).copy()
    H, W = g.shape
    bg = background(g)
    emit(g.copy(), "Start from the input: diamonds of colour 2 around empty centres.")
    centres = []
    for y in range(1, H - 1):
        for x in range(1, W - 1):
            if g[y, x] == bg:
                c = g[y - 1, x]
                if c != bg and g[y + 1, x] == c and g[y, x - 1] == c and g[y, x + 1] == c:
                    centres.append((y, x))
    from collections import defaultdict
    rows = defaultdict(list)
    cols = defaultdict(list)
    for (y, x) in centres:
        rows[y].append(x)
        cols[x].append(y)
    for y in sorted(rows):
        xs = sorted(rows[y])
        for a, b in zip(xs, xs[1:]):
            if b - a >= 4:
                g[y, a + 2:b - 1] = 1
                emit(g.copy(), f"Connect diamonds centred at ({y},{a}) and ({y},{b}) horizontally with colour 1.")
    for x in sorted(cols):
        ys = sorted(cols[x])
        for a, b in zip(ys, ys[1:]):
            if b - a >= 4:
                g[a + 2:b - 1, x] = 1
                emit(g.copy(), f"Connect diamonds centred at ({a},{x}) and ({b},{x}) vertically with colour 1.")
    emit(g.copy(), "Final grid: every pair of aligned neighbouring diamonds is linked tip to tip.")
    return g
